//! ↩️ delete-sampler leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfSampler;
use crate::artifacts::gltf::schema::mutations::delete_sampler::mutation::{validate, GltfDeleteSamplerPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{samplers_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.delete-sampler.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfDeleteSamplerInverseOperation { Insert { position: usize, item: GltfSampler }, Delete { index: usize, removed: GltfSampler }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfDeleteSamplerInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfDeleteSamplerPayload, pub operation: GltfDeleteSamplerInverseOperation }
async fn operation(payload: &GltfDeleteSamplerPayload, base: &GltfSnapshot) -> GltfDeleteSamplerInverseOperation { GltfDeleteSamplerInverseOperation::Insert { position: payload.index, item: base.document.samplers[payload.index].clone() } }
async fn touched_paths(payload: &GltfDeleteSamplerPayload) -> Vec<String> { vec![format!("document/samplers/{}", payload.index)] }
pub async fn validate_inverse(inverse: &GltfDeleteSamplerInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub async fn apply_inverse(inverse: &GltfDeleteSamplerInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfDeleteSamplerInverseOperation::Insert { position, .. } if *position > after.document.samplers.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/samplers", "position must be within the collection")), GltfDeleteSamplerInverseOperation::Delete { index, .. } if *index >= after.document.samplers.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/samplers", "index must address an item")), GltfDeleteSamplerInverseOperation::Move { index, position } if *index >= after.document.samplers.len() || *position >= after.document.samplers.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/samplers", "indices must address items")), GltfDeleteSamplerInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.samplers.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.samplers.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/samplers", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfDeleteSamplerInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Samplers, &Change::Insert(*position))?; next.document.samplers.insert(*position, item.clone());  }, GltfDeleteSamplerInverseOperation::Delete { index, .. } => { samplers_op(&mut next, GltfTopLevelFamily::Samplers, *index, None, None)?;  }, GltfDeleteSamplerInverseOperation::Move { index, position } => { samplers_op(&mut next, GltfTopLevelFamily::Samplers, *index, Some(*position), None)?;  }, GltfDeleteSamplerInverseOperation::Reorder { order } => { samplers_op(&mut next, GltfTopLevelFamily::Samplers, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(inverse: &GltfDeleteSamplerInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub async fn derive(payload: &GltfDeleteSamplerPayload, base: &GltfSnapshot) -> Result<GltfDeleteSamplerInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfDeleteSamplerInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
